import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { Tracer } from '../../src/index.ts';
import { SQLiteRepository } from '../../src/persistence/sqlite.ts';
import { createClient } from '../../src/client.ts';
import { startHeadlessServer } from '../../src/interfaces/headless-server.ts';
const journal = 'output/configuration-change/original-controlled-verification-completed.json';
assert.ok(!existsSync(journal));
const reportPath = 'projects/tracer/configuration-full-verification-execution.json';
const report = JSON.parse(readFileSync(reportPath));
const p = JSON.parse(readFileSync('output/configuration-change/original-follow-through-prepared.json'));
const opened = JSON.parse(readFileSync('output/configuration-change/original-controlled-verification-opened.json'));
const actor = { actor: 'tracer-configuration-change', reason: 'Record actual complete twelve-criterion software verification on the original exact after candidate, retain original evidence and require separate assessment closure/final publication audit.' };
const state = { actor, selection: opened.selection, commands: [] };
const save = extra => writeFileSync(journal, JSON.stringify({ ...state, ...extra }, null, 2) + '\n');
const repository = new SQLiteRepository('projects/tracer/tracer.sqlite'); let server;
try {
  const t = new Tracer(repository);
  assert.equal((await t.exportProject()).projectRevision, 177);
  server = await startHeadlessServer(t, { port: 0, provenance: actor });
  const client = createClient({ baseUrl: server.origin }); await client.connect();
  const analyze = () => client.read('/api/verification-analysis', opened.selection);
  const guards = a => ({ ...opened.selection, expectedSchemaVersion: a.view.model.context.schemaVersion, expectedProjectRevision: a.view.model.context.projectRevision, expectedEvidenceRevision: a.view.model.context.evidenceRevision, expectedCaseVersion: a.view.case.version });
  const mutation = (a, commandId, reason) => ({ ...guards(a), commandId, expectedAnalysisDigest: a.proposalDigest, reason });
  const write = async (operation, request) => { save({ pending: { operation, request } }); const result = await client.write('/api/verifications/' + operation, request); state.commands.push({ operation, request, result }); save({}); return result; };
  const initial = await analyze(); assert.equal(initial.view.case.version, 1); assert.equal(initial.executions.length, 0); assert.equal(initial.ready, false);
  assert.deepEqual(initial.view.scope.basis.criteria.map(x => x.id), report.results.map(x => x.criterionId));
  const frozen = await t.exportProject();
  const early = mutation(initial, 'configuration-original-reject-unexecuted-conclusion-2026-10-28', 'No performed results are recorded or selected yet; no controlled conclusion is justified.');
  await assert.rejects(client.write('/api/verifications/conclude', early));
  assert.equal(await t.evaluations.getOutcome(early.commandId), null); assert.deepEqual(await t.exportProject(), frozen); state.earlyConclusionRejectedWithoutWrites = true;
  const executionId = randomUUID(), methodId = initial.view.scope.basis.methods[0].entityId;
  await write('execute', { ...guards(initial), commandId: 'configuration-original-req035-execute-2026-10-28', executionId, membershipId: randomUUID(), title: 'Performed original twelve-criterion configuration-change software verification', methodId, source: { kind: 'performed' }, conditions: { report: { path: reportPath, sha256: createHash('sha256').update(readFileSync(reportPath)).digest('hex') }, candidateCommit: report.candidateCommit, candidateManifest: report.candidateManifest, declaredProcedure: report.methodDeclaration, verification: report.verification, scope: 'Actual performed software checks and exact task evidence; control outputs are concluded/accounted separately. No representative-human or physical/regulatory claim.' }, results: report.results.map(({ criterionId, outcome, actual, rationale }) => ({ criterionId, outcome, actual, rationale })), inputs: p.observed.map(x => ({ entityId: x.id, facet: 'content', observationId: x.observation.id, role: x.path })), relationshipInputs: [], additionalFields: {} });
  let a = await analyze(); assert.equal(a.view.case.version, 2); assert.equal(a.ready, false); assert.equal(a.executions.length, 1);
  await write('select', { ...mutation(a, 'configuration-original-req035-select-2026-10-28', 'Explicitly select the actual measured final-candidate checks and all twelve unchanged criterion results. Recording alone did not conclude verification.'), selections: report.results.map(x => ({ criterionId: x.criterionId, methodId, executionId })), accounting: [{ executionId, decision: 'selected', rationale: 'One actual complete software-verification activity covers every unchanged criterion and its selected candidate inputs; no earlier activity is overwritten.' }] });
  a = await analyze(); state.selectedAnalysis = a; save({}); assert.equal(a.ready, true);
  const conclusion = await write('conclude', mutation(a, 'configuration-original-req035-conclude-2026-10-28', 'All twelve original criteria have selected passing performed software results, exact after-candidate support and complete activity accounting. Conclude only this declared software scope; preserve the separate final pair-assessment and full-goal publication audit obligations.'));
  const final = await analyze(); assert.equal(final.completion.state, 'verified'); assert.equal(final.view.case.version, 4); assert.equal(final.executions.length, 1);
  assert.ok(final.criteria.every(x => x.status === 'passed'));
  assert.equal(final.view.scope.target.configurationId, p.after.id);
  const snapshot = await t.exportProject();
  for (const command of state.commands) {
    assert.deepEqual(await client.read('/api/evaluation-outcome', { commandId: command.request.commandId }), command.result);
    assert.deepEqual(await client.write('/api/verifications/' + command.operation, command.request), command.result);
  }
  assert.deepEqual(await t.exportProject(), snapshot);
  assert.deepEqual(await t.configurations.get(p.before.id), p.before); assert.deepEqual(await t.configurations.get(p.after.id), p.after);
  state.conclusion = conclusion; state.final = final;
  save({ status: 'original_twelve_criterion_exact_after_verification_completed', nativeRevision: snapshot.projectRevision, caseVersion: 4, criteria: 12, originalIntentRecoveryWithoutWrites: true, pairAssessmentAndFinalAuditPending: true });
  console.log(JSON.stringify({ nativeRevision: snapshot.projectRevision, caseVersion: 4, criteria: 12, completion: final.completion.state, target: p.after.id, conclusionReceiptId: conclusion.receipt.id }));
} finally { await server?.close(); repository.close(); }

import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { Tracer } from '../../src/index.ts';
import { SQLiteRepository } from '../../src/persistence/sqlite.ts';
import { createClient } from '../../src/client.ts';
import { startHeadlessServer } from '../../src/interfaces/headless-server.ts';
const journal = 'output/configuration-change/original-pair-assessment-completed.json'; assert.ok(!existsSync(journal));
const p = JSON.parse(readFileSync('output/configuration-change/original-follow-through-prepared.json'));
const opened = JSON.parse(readFileSync('output/configuration-change/original-controlled-verification-opened.json'));
const verified = JSON.parse(readFileSync('output/configuration-change/original-controlled-verification-completed.json'));
assert.equal(verified.final.completion.state, 'verified');
const actor = { actor: 'tracer-configuration-change', reason: 'Complete original actual capture-enhancement assessment using genuine twelve-criterion exact-after verification; preserve historical partial proofs and all discovered obligations.' };
const state = { actor, selection: p.selection, commands: [] };
const save = extra => writeFileSync(journal, JSON.stringify({ ...state, ...extra }, null, 2) + '\n');
const repository = new SQLiteRepository('projects/tracer/tracer.sqlite'); let server;
try {
  const t = new Tracer(repository); assert.equal((await t.exportProject()).projectRevision, 180);
  server = await startHeadlessServer(t, { port: 0, provenance: actor });
  const c = createClient({ baseUrl: server.origin }); await c.connect();
  const analyze = () => c.read('/api/assessment-analysis', p.selection);
  const base = v => ({ ...p.selection, expectedSchemaVersion: v.model.context.schemaVersion, expectedProjectRevision: v.model.context.projectRevision, expectedEvidenceRevision: v.model.context.evidenceRevision, expectedAssessmentVersion: v.assessment.version });
  const write = async (operation, request) => { save({ pending: { operation, request } }); const result = await c.write('/api/change-assessments/' + operation, request); state.commands.push({ operation, request, result }); save({}); return result; };
  let a = await analyze(); assert.equal(a.discovery, 'changed');
  await write('refresh', { ...base(a.view), commandId: 'configuration-original-final-assessment-refresh-2026-10-28', reason: 'Explicitly discover controlled opening, performed execution, selected results and conclusion while retaining all nine original obligations, historical phase judgments and the root action identity.' });
  a = await analyze(); assert.equal(a.discovery, 'current');
  const operations = new Map([[opened.result.receipt.id, 'opening'], ...verified.commands.map(x => [x.result.receipt.id, x.operation])]);
  const expected = new Set([...p.analysis.obligations.map(x => x.subject.kind + ':' + x.subject.id), ...[...operations.keys()].map(id => 'receipt:' + id)]);
  assert.deepEqual(new Set(a.obligations.map(x => x.subject.kind + ':' + x.subject.id)), expected); assert.equal(a.obligations.length, 13);
  const subject = { kind: 'entity', id: '90e3162a-a959-4d3f-95f0-c8c5e9324757' };
  const obligation = a.obligations.find(x => x.subject.kind === subject.kind && x.subject.id === subject.id);
  const prior = await t.changeAssessments.disposition(p.selection, subject); assert.equal(prior.decision, 'reverify'); assert.equal(prior.actions.length, 1); assert.equal(prior.actions[0].state, 'open'); assert.equal(obligation.hasUnknown, false);
  const support = { kind: 'receipt', id: verified.conclusion.receipt.id, mode: 'configuration', configurationId: p.after.id };
  const root = { ...base(a.view), commandId: 'configuration-original-root-action-complete-2026-10-28', subject, dispositionId: prior.id, membershipId: prior.membershipId, expectedDispositionVersion: prior.version, expectedBasisDigest: obligation.currentDigest, title: prior.title, decision: 'reverify', rationale: prior.rationale + ' Actual full final-source checks and twelve-criterion case v4 now conclude the exact after configuration. Complete the retained action using authenticated controlled proof; preserve all historical outcomes and unknown excluded dependencies.', actions: prior.actions.map(x => ({ ...x, state: 'done', resolution: 'Performed 714 unit/219 production browser/workbench and unchanged quality checks; all twelve unchanged criteria explicitly selected and concluded in case v4 for this exact after configuration. Final publication/preservation remains a separate completion audit.', support: [support] })), support: prior.data.support.map(x => x.reference), additionalFields: {} };
  const wrongCase = JSON.parse(readFileSync('output/configuration-change/real-target-verification.json'));
  const wrong = { ...root, commandId: 'configuration-original-reject-other-target-proof-2026-10-28', actions: root.actions.map(x => ({ ...x, support: [{ ...support, id: wrongCase.final.completion.receiptId }] })) };
  const frozen = await t.exportProject(); save({ pending: { operation: 'reject-wrong-target', request: wrong } });
  await assert.rejects(c.write('/api/change-assessments/disposition', wrong));
  assert.equal(await t.evaluations.getOutcome(wrong.commandId), null); assert.deepEqual(await t.exportProject(), frozen); state.otherTargetProofRejectedWithoutWrites = true; save({});
  await write('disposition', root);
  for (const [id, operation] of operations) {
    a = await analyze(); const subject = { kind: 'receipt', id }, o = a.obligations.find(x => x.subject.kind === 'receipt' && x.subject.id === id);
    assert.equal(o.state, 'undisposed'); assert.equal(o.hasUnknown, false);
    const receipt = await t.evidence.getReceipt(id);
    await write('disposition', { ...base(a.view), commandId: randomUUID(), subject, dispositionId: randomUUID(), membershipId: randomUUID(), expectedDispositionVersion: 0, expectedBasisDigest: o.currentDigest, title: `Account for original exact-target verification ${operation}`, decision: 'no_action', rationale: `This is the authenticated ${operation} control receipt for the current original-change verification case. Its outcome remains ${receipt.outcome.slice(0, 300)}. It introduces no separate engineering criterion beyond the twelve already executed. The retained root action is discharged by exact-after controlled conclusion ${support.id}; this judgment accounts only for the known selected requirement-input scope, without asserting full out-of-pair receipt applicability, rewriting a historical result or granting release approval.`, actions: [], support: [{ kind: 'receipt', id, mode: 'historical' }], additionalFields: {} });
  }
  a = await analyze(); assert.equal(a.discovery, 'current'); assert.ok(a.obligations.every(x => x.state === 'accounted' && x.openActions === 0));
  await write('close', { ...base(a.view), commandId: 'configuration-original-final-assessment-close-2026-10-28', reason: 'All thirteen selected candidates are individually accounted with current discovery. The original root action retains its identity and genuine twelve-criterion exact-after proof. Complete only this declared original software-change scope; excluded engineering dependencies remain unknown and release/human validation remain separate.' });
  const final = await analyze(); assert.equal(final.completion.state, 'completed'); assert.equal(final.discovery, 'current'); assert.equal(final.obligations.length, 13); assert.ok(final.obligations.every(x => x.state === 'accounted' && x.openActions === 0));
  const rootFinal = await t.changeAssessments.disposition(p.selection, subject); assert.equal(rootFinal.actions[0].id, prior.actions[0].id); assert.equal(rootFinal.actions[0].state, 'done');
  const verification = await t.verification.analyze(verified.selection); assert.equal(verification.completion.state, 'verified'); assert.equal(verification.view.case.version, 4);
  const snapshot = await t.exportProject();
  for (const x of state.commands) { assert.deepEqual(await c.read('/api/evaluation-outcome', { commandId: x.request.commandId }), x.result); assert.deepEqual(await c.write('/api/change-assessments/' + x.operation, x.request), x.result); }
  assert.deepEqual(await t.exportProject(), snapshot); assert.deepEqual(await t.configurations.get(p.before.id), p.before); assert.deepEqual(await t.configurations.get(p.after.id), p.after);
  state.final = final; state.root = rootFinal;
  save({ status: 'original_actual_change_follow_through_completed', nativeRevision: snapshot.projectRevision, candidates: 13, openActions: 0, controlledVerification: verified.selection, originalActionIdentityRetained: true, exactIntentRecoveryWithoutWrites: true, finalPublicationAndFullGoalAuditPending: true });
  console.log(JSON.stringify({ nativeRevision: snapshot.projectRevision, assessment: 'completed', discovery: final.discovery, candidates: 13, openActions: 0, verification: 'verified' }));
} finally { await server?.close(); repository.close(); }
